// VULNERABLE : la saisie est concatenee dans le texte SQL
app.get('/comptes', requireAuth, async (req, res) => {
  const nom = req.query.nom
  // si nom vaut  ' OR '1'='1  la requete renvoie toute la table
  const sql = "SELECT * FROM comptes WHERE nom = '" + nom + "'"
  const lignes = await db.query(sql)
  res.json(lignes)
})

// CORRIGE : requete parametree, la saisie reste une simple donnee
app.get('/comptes', requireAuth, async (req, res) => {
  const nom = req.query.nom
  // le $1 est un parametre : jamais interprete comme du SQL
  const lignes = await db.query(
    'SELECT * FROM comptes WHERE nom = $1',
    [nom]
  )
  res.json(lignes)
})

// VULNERABLE : les valeurs du corps sont inserees telles quelles
app.post('/connexion', async (req, res) => {
  // si motDePasse vaut { "$ne": null } la condition devient toujours vraie
  const user = await users.findOne({
    nom: req.body.nom,
    motDePasse: req.body.motDePasse
  })
  res.json({ connecte: !!user })
})

// CORRIGE : on force le type attendu (des chaines)
app.post('/connexion', async (req, res) => {
  const nom = String(req.body.nom || '')
  const motDePasse = String(req.body.motDePasse || '')
  // un objet comme { $ne: null } devient alors la chaine '[object Object]'
  const user = await users.findOne({ nom, motDePasse })
  res.json({ connecte: !!user })
})

Voici une recherche MongoDB vulnérable, qui insère directement un filtre reçu du client :

```javascript
app.get('/produits', async (req, res) => {
  // req.query.categorie peut etre un objet comme { "$ne": null }
  const produits = await db.produits.find({ categorie: req.query.categorie })
  res.json(produits)
})
```

Corrige ce code pour qu'une catégorie soit toujours traitée comme une simple chaîne et qu'aucun opérateur NoSQL ne puisse être injecté.

sections.solution:
On force le type de l'entrée en chaîne avant de l'utiliser dans le filtre. Ainsi, un objet comme `{ "$ne": null }` ne peut plus arriver jusqu'à la requête.

```javascript
app.get('/produits', async (req, res) => {
  const categorie = String(req.query.categorie || '')
  const produits = await db.produits.find({ categorie })
  res.json(produits)
})
```

En renfort, on peut valider que la catégorie fait partie d'une liste blanche de valeurs connues (par exemple 'livres', 'jeux', 'audio') et répondre 400 sinon. L'essentiel : ne jamais insérer dans la requête un objet reçu du client, car il pourrait porter des opérateurs.
